// Establece el cliente para solicitar el MTU m\xe1ximo del servidor (el valor por defecto es 23 si no se especifica)\n  \n    // Obtener una referencia al servicio que buscamos en el servidor BLE remoto.\n    BLERemoteService* pRemoteService = pClient->getService(serviceUUID);\n    if (pRemoteService == nullptr) {\n      Serial.print("No se pudo encontrar nuestro servicio UUID: ");\n      Serial.println(serviceUUID.toString().c_str());\n      pClient->disconnect();\n      return false;\n    }\n    Serial.println(" - Servicio encontrado");\n\n    // Obtener una referencia a la caracter\xedstica dentro del servicio del servidor BLE remoto.\n    pRemoteCharacteristic = pRemoteService->getCharacteristic(charUUID);\n    if (pRemoteCharacteristic == nullptr) {\n      Serial.print("No se pudo encontrar nuestra caracter\xedstica UUID: ");\n      Serial.println(charUUID.toString().c_str());\n      pClient->disconnect();\n      return false;\n    }\n    Serial.println(" - Caracter\xedstica encontrada");\n\n    // Leer el valor de la caracter\xedstica.\n    if(pRemoteCharacteristic->canRead()) {\n      String value = pRemoteCharacteristic->readValue();\n      Serial.print("El valor de la caracter\xedstica es: ");\n      Serial.println(value);\n    }\n\n    if(pRemoteCharacteristic->canNotify())\n      pRemoteCharacteristic->registerForNotify(notifyCallback);\n\n    connected = true;\n    return true;\n}\n/**\n * Escanear servidores BLE y encontrar el primero que publicite el servicio que estamos buscando.\n */\nclass MyAdvertisedDeviceCallbacks: public BLEAdvertisedDeviceCallbacks {\n /**\n   * Se llama para cada servidor BLE que publicite.\n   */\n  void onResult(BLEAdvertisedDevice advertisedDevice) {\n    Serial.print("Dispositivo BLE publicitado encontrado: ");\n    Serial.println(advertisedDevice.toString().c_str());\n\n    // Hemos encontrado un dispositivo, ahora vamos a ver si contiene el servicio que estamos buscando.\n    if (advertisedDevice.haveServiceUUID() && advertisedDevice.isAdvertisingService(serviceUUID)) {\n\n      BLEDevice::getScan()->stop();\n      myDevice = new BLEAdvertisedDevice(advertisedDevice);\n      doConnect = true;\n      doScan = true;\n\n    } // Servidor encontrado\n  } // onResult\n}; // MyAdvertisedDeviceCallbacks\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial.println("Iniciando la aplicaci\xf3n Cliente BLE de Arduino...");\n  BLEDevice::init("");\n\n  // Obtener un esc\xe1ner y establecer el callback que queremos usar para ser informados cuando\n  // detectemos un nuevo dispositivo. Especificar que queremos escaneo activo y comenzar el\n  // escaneo para que dure 5 segundos.\n  BLEScan* pBLEScan = BLEDevice::getScan();\n  pBLEScan->setAdvertisedDeviceCallbacks(new MyAdvertisedDeviceCallbacks());\n  pBLEScan->setInterval(1349);\n  pBLEScan->setWindow(449);\n  pBLEScan->setActiveScan(true);\n  pBLEScan->start(5, false);\n} // Fin de setup.\n\n// Esta es la funci\xf3n principal del bucle de Arduino.\nvoid loop() {\n  // Si la bandera "doConnect" es verdadera, significa que hemos escaneado y encontrado el\n  // servidor BLE deseado con el que deseamos conectar. Ahora nos conectamos a \xe9l. Una vez que estamos \n  // conectados, establecemos la bandera de conexi\xf3n en verdadera.\n  if (doConnect == true) {\n    if (connectToServer()) {\n      Serial.println("Ahora estamos conectados al servidor BLE.");\n    } else {\n      Serial.println("No hemos podido conectar al servidor; no haremos nada m\xe1s.");\n    }\n    doConnect = false;\n  }\n\n  // Si estamos conectados a un servidor BLE remoto, actualizamos la caracter\xedstica cada vez que\n  // se alcanza con el tiempo actual desde el arranque.\n  if (connected) {\n    String newValue = "Tiempo desde el arranque: " + String(millis()/1000);\n    Serial.println("Estableciendo nuevo valor de la caracter\xedstica a \\"" + newValue + "\\"");\n    \n    // Establecer el valor de la caracter\xedstica como el array de bytes que en realidad es una cadena.\n    pRemoteCharacteristic->writeValue(newValue.c_str(), newValue.length());\n  }else if(doScan){\n    BLEDevice::getScan()->start(0);  // Este es solo un ejemplo para iniciar el escaneo despu\xe9s de la desconexi\xf3n, lo m\xe1s probable es que haya una mejor forma de hacerlo en Arduino\n  }\n  \n  delay(1000); // Retraso de un segundo entre los bucles.\n} // Fin del loop\n'})}),"\n",(0,s.jsxs)(n.admonition,{type:"tip",children:[(0,s.jsx)(n.p,{children:"Si ya has actualizado tu placa de desarrollo ESP32 a la versi\xf3n 3.0.0 o superior, debes modificar algunas partes del c\xf3digo para que sea compatible:"}),(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.code,{children:"std::string value = pRemoteCharacteristic->readValue();"})," cambia a ",(0,s.jsx)(n.code,{children:"String value = pRemoteCharacteristic->readValue();"})]}),"\n"]})]}),"\n",(0,s.jsx)(n.p,{children:"El programa anterior convertir\xe1 a la XIAO en un cliente y buscar\xe1 dispositivos Bluetooth cercanos. Cuando el UUID del dispositivo Bluetooth coincida con el UUID que proporcionaste, se conectar\xe1 al dispositivo y obtendr\xe1 el valor de su caracter\xedstica."}),"\n",(0,s.jsx)("div",{style:{textAlign:"center"},children:(0,s.jsx)("img",{src:"https://files.seeedstudio.com/wiki/SeeedStudio-XIAO-ESP32S3/img/60.png",style:{width:800,height:"auto"}})}),"\n",(0,s.jsx)(n.h4,{id:"anotaci\xf3n-del-programa-1",children:"Anotaci\xf3n del programa"}),"\n",(0,s.jsx)(n.p,{children:"Echemos un vistazo r\xe1pido a c\xf3mo funciona el c\xf3digo de ejemplo para el servidor BLE. Comienza importando las bibliotecas necesarias para las capacidades BLE. Luego, es necesario definir un UUID para el Servicio y la Caracter\xedstica."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-c",children:'#define SERVICE_UUID "4fafc201-1fb5-459e-8fcc-c5c9c331914b"\n#define CHARACTERISTIC_UUID "beb5483e-36e1-4688-b7f5-ea07361b26a8"\n'})}),"\n",(0,s.jsxs)(n.p,{children:["Puedes dejar los U